let narrowFontLoadPromise: Promise<void> | null = null;

/**
 * Wait until EzzyNarrow 400/700 is usable for print or html2canvas capture.
 * Resolves after the loads plus document.fonts.ready, or after timeoutMs
 * (default 3s) — callers must print anyway on timeout.
 */
export function ensureLabelNarrowFontLoaded(timeoutMs = 3000): Promise<void> {
  if (narrowFontLoadPromise) return narrowFontLoadPromise;
  narrowFontLoadPromise = (async (): Promise<void> => {
    try {
      const fonts = document.fonts;
      if (!fonts || typeof fonts.load !== 'function') return;
      const timeout = new Promise<void>((resolve) => {
        window.setTimeout(resolve, timeoutMs);
      });
      await Promise.race([
        (async (): Promise<void> => {
          try {
            await fonts.load('400 10px EzzyNarrow');
            await fonts.load('700 10px EzzyNarrow');
          } catch {
            // Fall through to fonts.ready below.
          }
          try {
            await fonts.ready;
          } catch {
            // Ignore — caller prints anyway.
          }
        })(),
        timeout,
      ]);
    } catch {
      // Ignore — caller prints anyway.
    }
  })();
  return narrowFontLoadPromise;
}
